WITH parsed AS (SELECT id, log_ts, level, latency_ms, status_code, context, CAST((status_code & 8) != 0 AS INT) AS has_fault, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace FROM app_logs WHERE HOUR(log_ts) BETWEEN 7 AND 13) SELECT id, status_code, has_trace, AVG(status_code) OVER (PARTITION BY level ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) status_code_avg_1h, LAST_VALUE(has_fault) IGNORE NULLS OVER (PARTITION BY level ORDER BY has_fault, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_has_fault, LEAD(has_fault, 2) OVER w_running next_has_fault, AVG(status_code) OVER (PARTITION BY level ORDER BY latency_ms, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) status_code_avg_5 FROM parsed WINDOW w_running AS (PARTITION BY level ORDER BY status_code, id);
